PREFIX : <http://valuenet/ontop/>
{
  SELECT ?district (COUNT(?city) AS ?cityCount)
  WHERE {
    ?city <http://valuenet/ontop/population> ?population.
    ?city <http://valuenet/ontop/district> ?district.
